/**
 * rules.test.ts — the TS mirror must agree with the Python engine on every
 * shared test vector (data/test-vectors.json, generated by the pipeline),
 * plus unit checks on the break rules.
 */
import { describe, expect, it } from "vitest";
import {
  correctionDraft,
  detectBreaks,
  recommendedAction,
  routeOrder,
  scoreOrder,
} from "./rules";
import type { FlatOrder } from "./types";
import vectorsJson from "../public/data/test-vectors.json";

function order(over: Partial<FlatOrder> = {}): FlatOrder {
  return {
    order_id: "test-order-1",
    customer_id: "cust-1",
    customer_state: "SP",
    purchase_date: "2017-11-15",
    approved_date: "2017-11-15",
    status: "delivered",
    payments: [{ type: "credit_card", sequential: 1, installments: 1, value: 100 }],
    items: [{ price: 90, freight: 10, seller_id: "s1", shipping_limit_date: "2017-11-20" }],
    delivered_carrier_date: "2017-11-18",
    delivered_customer_date: "2017-11-25",
    estimated_delivery_date: "2017-11-25",
    ...over,
  };
}

describe("shared test vectors (Python/TS contract)", () => {
  it("has 12 vectors, one per break profile", () => {
    expect(vectorsJson.vectors).toHaveLength(12);
    expect(new Set(vectorsJson.vectors.map((v) => v.label)).size).toBe(12);
  });

  for (const v of vectorsJson.vectors) {
    it(`${v.label} agrees: ${v.expected_codes.join("+") || "clean"} ${v.expected_score} ${v.expected_route} ${v.expected_action}`, () => {
      const breaks = detectBreaks(v.order as FlatOrder);
      const { score } = scoreOrder(v.order as FlatOrder, breaks);
      const route = routeOrder(v.order as FlatOrder, breaks, score);
      const [action] = recommendedAction(v.order as FlatOrder, breaks);
      expect(breaks.map((b) => b.code).sort()).toEqual([...v.expected_codes].sort());
      expect(score).toBe(v.expected_score);
      expect(route).toBe(v.expected_route);
      expect(action).toBe(v.expected_action);
    });
  }
});

describe("break rules", () => {
  it("clean order has no breaks and no action", () => {
    const o = order();
    const breaks = detectBreaks(o);
    expect(breaks).toEqual([]);
    const { score } = scoreOrder(o, breaks);
    // No breaks, but the age point still applies: purchased 2017-11-15 is
    // 51 days before the 2018-01-05 close, so score is 1, not 0.
    expect(score).toBe(1);
    expect(routeOrder(o, breaks, score)).toBe("MONITOR");
    expect(recommendedAction(o, breaks)[0]).toBe("NO_ACTION");
  });

  it("B1 underpayment scores 41 and routes REVIEW", () => {
    const o = order({ payments: [{ type: "credit_card", sequential: 1, installments: 1, value: 80 }] });
    const breaks = detectBreaks(o);
    expect(breaks.map((b) => b.code)).toEqual(["B1"]);
    expect(breaks[0].delta).toBe(-20);
    const { score } = scoreOrder(o, breaks);
    expect(score).toBe(41);
    expect(routeOrder(o, breaks, score)).toBe("REVIEW");
    expect(recommendedAction(o, breaks)[0]).toBe("POST_CORRECTION");
  });

  it("B1 is suppressed on canceled orders (B2 rules) and unpaid deliveries (B6 rules)", () => {
    expect(detectBreaks(order({ status: "canceled" })).map((b) => b.code)).toEqual(["B2"]);
    expect(detectBreaks(order({ payments: [] })).map((b) => b.code)).toEqual(["B6"]);
  });

  it("B2 large refund escalates on the money rule", () => {
    const o = order({
      status: "canceled",
      payments: [{ type: "credit_card", sequential: 1, installments: 1, value: 600 }],
      items: [{ price: 550, freight: 50, seller_id: "s1", shipping_limit_date: "2017-11-20" }],
    });
    const breaks = detectBreaks(o);
    const { score } = scoreOrder(o, breaks);
    expect(routeOrder(o, breaks, score)).toBe("ESCALATE");
    expect(recommendedAction(o, breaks)[0]).toBe("ISSUE_REFUND");
  });

  it("B3 paid-not-shipped and B4/B5 late rules fire with day counts", () => {
    expect(detectBreaks(order({ status: "unavailable", items: [] })).map((b) => b.code)).toEqual(["B3"]);
    const late = detectBreaks(order({ delivered_customer_date: "2017-11-28" }));
    expect(late[0].code).toBe("B4");
    expect(late[0].days_late).toBe(3);
    const over = detectBreaks(order({ delivered_carrier_date: "2017-11-22" }));
    expect(over[0].code).toBe("B5");
    expect(over[0].days_over).toBe(2);
  });

  it("B7 duplicate sequence isolates when totals agree", () => {
    const o = order({
      payments: [
        { type: "credit_card", sequential: 1, installments: 1, value: 50 },
        { type: "credit_card", sequential: 1, installments: 1, value: 50 },
      ],
    });
    expect(detectBreaks(o).map((b) => b.code)).toEqual(["B7"]);
  });

  it("over-collection journal holds the excess as refunds payable", () => {
    const o = order({ payments: [{ type: "credit_card", sequential: 1, installments: 1, value: 120 }] });
    const drafts = correctionDraft(o, detectBreaks(o));
    expect(drafts[0].title).toBe("Correcting journal — over-collection");
    expect(drafts[0].lines[1]).toContain("refunds payable");
  });

  it("score caps at 100", () => {
    const fabricated = [
      { code: "B1" as const, delta: -5000, detail: "" },
      { code: "B2" as const, refund_owed: 5000, detail: "" },
      { code: "B3" as const, amount_at_risk: 5000, detail: "" },
      { code: "B4" as const, days_late: 90, detail: "" },
      { code: "B5" as const, days_over: 90, detail: "" },
      { code: "B6" as const, amount_at_risk: 5000, detail: "" },
      { code: "B7" as const, detail: "" },
      { code: "B8" as const, detail: "" },
    ];
    const { score } = scoreOrder(order(), fabricated);
    expect(score).toBe(100);
  });
});
